llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Celiprolol, the closest analogue sharing the tert-butylamino-2-hydroxypropoxy aryl ether and a urea substituent, has a human oral bioavailability of 30–70%, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Pafenolol, another urea-containing aryloxypropanolamine beta-blocker, has an absolute oral bioavailability of about 27% at a 25 mg dose, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Penbutolol, which shares the tert-butylamino hydroxypropoxy motif, has an absolute oral bioavailability of 90% in humans, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Prenalterol, one of the lower-bioavailability analogues, still reaches about 25% systemic availability, indicating that even the least favorable related beta-blockers remain above the 20% cutoff.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence from structurally related beta-blockers indicates oral bioavailability above 20%, with values ranging from about 25% to 100%. The closest analogues containing urea and tert-butylamino groups (celiprolol, pafenolol) have F values of 27–70%. Rifampin co-treatment may lower F through enzyme or transporter induction, but no affirmative evidence suggests it would reduce the query below 20%; therefore the prediction is high.",
  "evidence_gaps": [
    "No direct experimental data for the query molecule under rifampin co-treatment.",
    "Unknown whether the query is a substrate for CYP3A4 or P-glycoprotein, which would determine the magnitude of rifampin's effect.",
    "Oral bioavailability of the query itself has not been measured.",
    "Dose-dependent bioavailability seen in some analogues (e.g., celiprolol, pafenolol) adds uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

